+@namespace sv_a2d4414cab0a405680837900b344277b.Components.JobApplication
+
+<nav class="step-indicator" aria-label="Application progress">
+    @for (int i = 0; i < StepNames.Length; i++)
+    {
+        var step = i;
+        var cssClass = step == CurrentStep ? "step active"
+                     : step < CurrentStep ? "step completed"
+                     : "step future";
+
+        <button class="@cssClass"
+                disabled="@(step > CurrentStep)"
+                @onclick="() => OnStepClicked.InvokeAsync(step)"
+                aria-current="@(step == CurrentStep ? "step" : null)">
+            <span class="step-number">
+                @if (step < CurrentStep)
+                {
+                    <span class="checkmark">✓</span>
+                }
+                else
+                {
+                    @(step + 1)
+                }
+            </span>
+            <span class="step-label">@StepNames[step]</span>
+        </button>
+
+        @if (i < StepNames.Length - 1)
+        {
+            <span class="step-connector @(i < CurrentStep ? "completed" : "")"></span>
+        }
+    }
+</nav>
+
+@code {
+    private static readonly string[] StepNames =
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
