@page "/apply"
@rendermode InteractiveServer
@using sv_a2d4414cab0a405680837900b344277b.Components.JobApplication
@using sv_a2d4414cab0a405680837900b344277b.Models
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personalInfo"
                              OnNext="NextStep"
                              ValidateEmail="AppService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="v => _coverLetter = v"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfoModel _personalInfo = new();
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private void NextStep() => _currentStep = Math.Min(_currentStep + 1, 4);
    private void PreviousStep() => _currentStep = Math.Max(_currentStep - 1, 0);

    private void GoToStep(int step)
    {
        if (step <= _currentStep)
            _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personalInfo.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter);

        return await AppService.SubmitApplicationAsync(application);
    }
}

