    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    gap: 0.4rem;
    min-width: 90px;
    transition: opacity 0.2s;
}

.step-indicator .step.future {
    opacity: 0.4;
    cursor: default;
}

.step-indicator .step.active .step-number {
    background: #4361ee;
    color: #fff;
    font-weight: 700;
}

.step-indicator .step.completed .step-number {
    background: #2ec4b6;
    color: #fff;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e0e0e0;
    color: #666;
    font-size: 0.9rem;
    font-weight: 600;
    transition: background 0.2s, color 0.2s;
