.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #e0e0e0;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

